begin;
create table if not exists public.angelcare_marketplace_provider_profiles(
 id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('PROV-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),canonical_app_user_id uuid,canonical_carelink_agent_id uuid,provider_type text not null check(provider_type in('caregiver','childcare_agent','trainer','facilitator','activity_specialist','provider_organization','contractor')),display_name text not null,email text,phone text,emergency_contact jsonb not null default '{}',territory_id uuid,tenant_id uuid references public.angelcare_marketplace_partner_tenants(id),onboarding_status text not null default 'in_progress' check(onboarding_status in('not_started','in_progress','review','ready','blocked','completed','archived')),operational_status text not null default 'pending' check(operational_status in('pending','active','restricted','temporarily_blocked','suspended','inactive','archived')),service_categories text[] not null default '{}',age_group_competencies text[] not null default '{}',languages text[] not null default '{fr}',operational_zones text[] not null default '{}',compensation_model jsonb not null default '{}',owner_id uuid,next_action text,risk_level text not null default 'normal' check(risk_level in('low','normal','high','critical')),created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_provider_service_qualifications(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id) on delete cascade,service_key text not null,age_groups text[] not null default '{}',territories text[] not null default '{}',qualification_source text not null,evidence jsonb not null default '{}',status text not null default 'pending' check(status in('pending','qualified','restricted','expired','revoked')),approved_by uuid,approved_at timestamptz,expires_at timestamptz,unique(provider_id,service_key));
create table if not exists public.angelcare_marketplace_provider_documents(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id) on delete cascade,document_type text not null,status text not null default 'requested' check(status in('requested','submitted','under_review','valid','rejected','expiring','expired','superseded','archived')),file_reference text,issuing_authority text,issue_date date,expires_at timestamptz,expiry_bucket text not null default 'future' check(expiry_bucket in('none','expired','next_30_days','future')),reviewer_id uuid,reviewed_at timestamptz,rejection_reason text,sensitivity text not null default 'confidential',version int not null default 1,territory_id uuid,tenant_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_provider_certifications(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id) on delete cascade,academy_certificate_id uuid references public.angelcare_marketplace_academy_certificates(id),certification_key text not null,source text not null,status text not null default 'pending' check(status in('pending','active','expiring','expired','suspended','revoked')),issued_at timestamptz,expires_at timestamptz,expiry_bucket text not null default 'future' check(expiry_bucket in('none','expired','next_30_days','future')),mandatory_for_services text[] not null default '{}',restrictions jsonb not null default '{}',territory_id uuid,tenant_id uuid,unique(provider_id,certification_key,source));
create table if not exists public.angelcare_marketplace_provider_availability_rules(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id) on delete cascade,weekday int not null check(weekday between 0 and 6),starts_at time not null,ends_at time not null,timezone text not null default 'Africa/Casablanca',zones text[] not null default '{}',service_categories text[] not null default '{}',max_daily_minutes int not null default 480,max_weekly_minutes int not null default 2400,active boolean not null default true,updated_by uuid,updated_at timestamptz not null default now(),unique(provider_id,weekday,starts_at,ends_at));
create table if not exists public.angelcare_marketplace_provider_availability_exceptions(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,availability_status text not null check(availability_status in('available','unavailable','leave','emergency_available')),reason text,conflict_flag boolean not null default false,approved_by uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_provider_operational_eligibility(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id) on delete cascade,status text not null check(status in('not_started','incomplete','pending_review','eligible','eligible_with_restrictions','temporarily_blocked','suspended','expired','ineligible')),eligible_services text[] not null default '{}',eligible_age_groups text[] not null default '{}',eligible_territories text[] not null default '{}',restrictions jsonb not null default '{}',blockers text[] not null default '{}',score int not null default 0 check(score between 0 and 100),calculated_at timestamptz not null default now(),calculated_by uuid,override_reason text,expires_at timestamptz,territory_id uuid,tenant_id uuid);
create table if not exists public.angelcare_marketplace_provider_assignments(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id),mission_id uuid not null,role_key text not null,status text not null default 'proposed' check(status in('proposed','assigned','awaiting_acceptance','accepted','rejected','cancelled','completed')),proposed_at timestamptz,accepted_at timestamptz,rejected_at timestamptz,rejection_reason text,assigned_by uuid,territory_id uuid,tenant_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider_id,mission_id,role_key));
create table if not exists public.angelcare_marketplace_provider_performance_events(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id),mission_id uuid,event_type text not null,score numeric(6,2),severity text,details jsonb not null default '{}',recorded_by uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_provider_payable_eligibility(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id),mission_id uuid not null,status text not null default 'not_eligible' check(status in('not_eligible','pending_execution','pending_report','pending_validation','eligible','held','disputed','approved','exported','paid','reversed')),checklist jsonb not null default '{}',blockers text[] not null default '{}',compensation_amount numeric(16,2),currency_label text not null default 'Dh',reviewed_by uuid,reviewed_at timestamptz,review_reason text,exported_at timestamptz,paid_at timestamptz,territory_id uuid,tenant_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider_id,mission_id));

create or replace function public.angelcare_marketplace_recalculate_provider_eligibility(p_provider_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.angelcare_marketplace_provider_profiles;valid_docs int;expired_docs int;active_certs int;expired_certs int;critical_incidents int;score int;state text;blockers text[]:='{}';r public.angelcare_marketplace_provider_operational_eligibility;begin select * into p from public.angelcare_marketplace_provider_profiles where id=p_provider_id for update;if p.id is null then raise exception 'Provider not found';end if;select count(*) filter(where status='valid'),count(*) filter(where status in('expired','rejected')) into valid_docs,expired_docs from public.angelcare_marketplace_provider_documents where provider_id=p.id;select count(*) filter(where status in('active','issued','renewed','expiring')),count(*) filter(where status in('expired','suspended','revoked')) into active_certs,expired_certs from (
 select status from public.angelcare_marketplace_provider_certifications where provider_id=p.id
 union all
 select status from public.angelcare_marketplace_academy_certificates where learner_provider_id=p.id
) certification_evidence;begin select count(*) into critical_incidents from public.angelcare_marketplace_operations_incidents where provider_id=p.id and severity in('critical','emergency') and status not in('resolved','closed');exception when undefined_table then critical_incidents:=0;end;if p.operational_status='suspended' then blockers:=array_append(blockers,'provider_suspended');end if;if p.onboarding_status<>'completed' then blockers:=array_append(blockers,'onboarding_incomplete');end if;if expired_docs>0 then blockers:=array_append(blockers,'documents_expired_or_rejected');end if;if expired_certs>0 then blockers:=array_append(blockers,'certification_invalid');end if;if active_certs=0 then blockers:=array_append(blockers,'no_active_certification');end if;if critical_incidents>0 then blockers:=array_append(blockers,'critical_incident_open');end if;score:=greatest(0,100-(cardinality(blockers)*22));if p.operational_status='suspended' then state:='suspended';elsif critical_incidents>0 or expired_docs>0 then state:='temporarily_blocked';elsif cardinality(blockers)=0 then state:='eligible';elsif score>=60 then state:='eligible_with_restrictions';else state:='incomplete';end if;insert into public.angelcare_marketplace_provider_operational_eligibility(provider_id,status,eligible_services,eligible_age_groups,eligible_territories,restrictions,blockers,score,calculated_by,territory_id,tenant_id) values(p.id,state,case when state in('eligible','eligible_with_restrictions') then p.service_categories else '{}' end,case when state in('eligible','eligible_with_restrictions') then p.age_group_competencies else '{}' end,case when p.territory_id is null then '{}' else array[p.territory_id::text] end,jsonb_build_object('operational_zones',p.operational_zones),blockers,score,p_actor_id,p.territory_id,p.tenant_id) returning * into r;update public.angelcare_marketplace_provider_profiles set operational_status=case when state='eligible' then 'active' when state='eligible_with_restrictions' then 'restricted' when state='suspended' then 'suspended' else 'temporarily_blocked' end,updated_at=now(),updated_by=p_actor_id where id=p.id;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_decide_payable_eligibility(p_payable_id uuid,p_action text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_provider_payable_eligibility;target text;begin select * into r from public.angelcare_marketplace_provider_payable_eligibility where id=p_payable_id for update;if r.id is null then raise exception 'Payable eligibility not found';end if;if p_action='approve' then if r.status not in('eligible','pending_validation') or cardinality(r.blockers)>0 then raise exception 'Payable evidence is incomplete';end if;target:='approved';elsif p_action='hold' then target:='held';elsif p_action='dispute' then target:='disputed';elsif p_action='reverse' then target:='reversed';else raise exception 'Unsupported payable action';end if;update public.angelcare_marketplace_provider_payable_eligibility set status=target,reviewed_by=p_actor_id,reviewed_at=now(),review_reason=p_reason,updated_at=now() where id=r.id returning * into r;return to_jsonb(r);end$$;

insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.providers.view','Voir Provider Workforce','Provider Workforce',false),('marketplace.providers.create','Créer un provider','Provider Workforce',true),('marketplace.providers.manage','Gérer les providers','Provider Workforce',true),('marketplace.providers.documents.review','Réviser les documents','Provider Workforce',true),('marketplace.providers.certifications.review','Réviser les certifications','Provider Workforce',true),('marketplace.providers.availability.manage','Gérer les disponibilités','Provider Workforce',true),('marketplace.providers.eligibility.review','Réviser l’éligibilité','Provider Workforce',true),('marketplace.providers.suspend','Suspendre un provider','Provider Workforce',true),('marketplace.providers.performance.view','Voir la performance','Provider Workforce',false),('marketplace.providers.payable_eligibility.review','Réviser l’éligibilité payable','Provider Workforce',true),('marketplace.providers.self.access','Accéder à son espace provider','Provider Workforce',false),('marketplace.providers.missions.view','Voir ses missions','Provider Workforce',false),('marketplace.providers.reports.submit','Soumettre ses rapports','Provider Workforce',true)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.providers.%' on conflict do nothing;
insert into public.angelcare_marketplace_modules(module_key,name,description,route_prefix,module_type,audience,status,enabled,required_permissions,required_dependencies,territory_aware,tenant_aware,locale_aware,health_status,owner_role,introduced_by_mega_zip) values('provider-workforce','Provider Workforce Operations','Onboarding, documents, certifications, disponibilité et éligibilité.','/angelcare-marketplace/admin/providers','operating_engine',array['admin','executive','provider']::text[],'enabled',true,array['marketplace.providers.view']::text[],array['academy-engine','territory-os']::text[],true,true,true,'healthy','provider_operations_manager',17) on conflict(module_key) do update set status='enabled',enabled=true,route_prefix=excluded.route_prefix,required_permissions=excluded.required_permissions,updated_at=now();
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.providers.enabled','Provider Workforce','Onboarding et éligibilité provider gouvernés.',true,'active','Ultra Delivery 4/5 · Original MZ17') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();

alter table public.angelcare_marketplace_provider_profiles enable row level security;alter table public.angelcare_marketplace_provider_service_qualifications enable row level security;alter table public.angelcare_marketplace_provider_documents enable row level security;alter table public.angelcare_marketplace_provider_certifications enable row level security;alter table public.angelcare_marketplace_provider_availability_rules enable row level security;alter table public.angelcare_marketplace_provider_availability_exceptions enable row level security;alter table public.angelcare_marketplace_provider_operational_eligibility enable row level security;alter table public.angelcare_marketplace_provider_assignments enable row level security;alter table public.angelcare_marketplace_provider_performance_events enable row level security;alter table public.angelcare_marketplace_provider_payable_eligibility enable row level security;
revoke all on table public.angelcare_marketplace_provider_profiles,public.angelcare_marketplace_provider_service_qualifications,public.angelcare_marketplace_provider_documents,public.angelcare_marketplace_provider_certifications,public.angelcare_marketplace_provider_availability_rules,public.angelcare_marketplace_provider_availability_exceptions,public.angelcare_marketplace_provider_operational_eligibility,public.angelcare_marketplace_provider_assignments,public.angelcare_marketplace_provider_performance_events,public.angelcare_marketplace_provider_payable_eligibility from anon,authenticated;
grant all on table public.angelcare_marketplace_provider_profiles,public.angelcare_marketplace_provider_service_qualifications,public.angelcare_marketplace_provider_documents,public.angelcare_marketplace_provider_certifications,public.angelcare_marketplace_provider_availability_rules,public.angelcare_marketplace_provider_availability_exceptions,public.angelcare_marketplace_provider_operational_eligibility,public.angelcare_marketplace_provider_assignments,public.angelcare_marketplace_provider_performance_events,public.angelcare_marketplace_provider_payable_eligibility to service_role;
grant execute on function public.angelcare_marketplace_recalculate_provider_eligibility(uuid,uuid),public.angelcare_marketplace_decide_payable_eligibility(uuid,text,text,uuid) to service_role;
create index if not exists ac_provider_scope_idx on public.angelcare_marketplace_provider_profiles(territory_id,tenant_id,operational_status,updated_at desc);create index if not exists ac_provider_doc_expiry_idx on public.angelcare_marketplace_provider_documents(provider_id,status,expires_at);
commit;
